void log_message(Log* log, const char* message) {
  if (log == NULL || message == NULL) {
    return;
  }

  if (log->file == NULL) {
    log->file = fopen(log->filename, "a");
    if (log->file == NULL) {
      fprintf(stderr, "Failed to open log file: %s\n", log->filename);
      return;
    }
  }

  time_t now = time(NULL);
  struct tm* local_time = localtime(&now);
  char time_str[20];
  strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", local_time);

  fprintf(log->file, "[%s] %s\n", time_str, message);
  fflush(log->file); // Ensure the message is written immediately
}

int main() {
  Log* log = create_log("app.log");
  if (log == NULL) {
    fprintf(stderr, "Failed to create log.\n");
    return 1;
  }

  log_message(log, "Application started");
  log_message(log, "Processing data...");
  log_message(log, "Data processed successfully");

  destroy_log(log);
  return 0;
}
```

### Explanation

- **create_log**: Initializes a new `Log` structure, opens the specified file in append mode, and returns the pointer.
- **destroy_log**: Closes the file and frees the memory allocated for the `Log` structure.
- **log_message**: Appends a timestamped message to the log file. It ensures the file is open, writes the message with a timestamp, and flushes the buffer to ensure immediate writing.

### Notes

- The log file is opened in append mode (`"a"`), so each call to `log_message` adds a new line without overwriting previous content.
- The `fflush` call ensures that the message is written to the file immediately, which is important for real-time logging.
- Error handling is included for file operations to handle cases where the file cannot be opened.

