{
    if (m_process_handle == NULL)
        return NULL;

    HMODULE* modules = NULL;
    DWORD bytes_returned = 0;

    if (!EnumProcessModules(m_process_handle, modules, 0, &bytes_returned))
        return NULL;

    modules = (HMODULE*)malloc(bytes_returned);

    if (!EnumProcessModules(m_process_handle, modules, bytes_returned, &bytes_returned))
    {
        free(modules);
        return NULL;
    }

    char module_name_buffer[1024] = { 0 };

    for (int i = 0; i < (bytes_returned / sizeof(HMODULE)); i++)
    {
        if (GetModuleBaseNameA(m_process_handle, modules[i], module_name_buffer, sizeof(module_name_buffer)))
        {
            if (strcmp(module_name_buffer, module_name) == 0)
            {
                free(modules);
                return (DWORD*)modules[i];
            }
        }
    }

    free(modules);
    return NULL;
} // GetModuleBaseAddress() function. Returns the base address of the module. If not found, returns NULL. // 

DWORD CProcess::GetProcessId(const char* process_name)
{
    HANDLE hSnapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, NULL);
    if (hSnapshot == INVALID_HANDLE_VALUE)
        return 0;

    PROCESSENTRY32 pe;
    pe.dwSize = sizeof(PROCESSENTRY32);

    if (Process32First(hSnapshot, &pe))
    {
        do
        {
            if (strcmp(pe.szExeFile, process_name) == 0)
            {
                CloseHandle(hSnapshot);
                return pe.th32ProcessID;
            }
        } while (Process32Next(hSnapshot, &pe));
    }

    CloseHandle(hSnapshot);
    return 0;
} // GetProcessId() function. Returns the process ID of the given process name. If not found, returns 0. // 

