### 1. **Backend (Node.js + Express)**
You need to set up an Express server that serves your React app and handles the API routes.

#### `server.js` (or `app.js`)
```javascript
const express = require('express');
const path = require('path');
const app = express();
const PORT = process.env.PORT || 5000;

// Serve static files from the React app
app.use(express.static(path.join(__dirname, 'client/build')));

// API route
app.get('/api/data', (req, res) => {
  res.json({ message: 'Hello from the server!' });
});

// Catch-all route to serve the React app
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'client/build', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

### 2. **Client-Side (React)**
In your React app, you can make a fetch request to the `/api/data` endpoint. Since the server is serving the React app, the request will be handled by the server, and the client will receive the response.

#### Example in a React component:
```javascript
import React, { useEffect, useState } from 'react';

function App() {
  const [data, setData] = useState(null);

  useEffect(() => {
    fetch('/api/data')
      .then(response => response.json())
      .then(data => setData(data))
      .catch(error => console.error('Error fetching data:', error));
  }, []);

  return (
    <div>
      <h1>React App</h1>
      {data ? <p>{data.message}</p> : <p>Loading...</p>}
    </div>
  );
}

export default App;
```

### 3. **Project Structure**
Ensure your project structure looks like this:
```
your-project/
├── server.js
├── package.json
├── client/
│   ├── package.json
│   ├── public/
│   ├── src/
│   └── build/
```

### 4. **Start the Server**
Make sure you have both the server and client dependencies installed. You can start the server with:

```bash
node server.js
```

